<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
require_business_portal_access();
require dirname(__DIR__,2).'/app/BusinessAccountPortalService.php';
$pdo=db();$service=new BusinessAccountPortalService($pdo);$error='';$destinationId=max(0,(int)($_POST['destination_id']??$_GET['destination_id']??0));
if(($_GET['search']??'')==='1'){
    header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
    try{
        $category=(string)($_GET['category']??'');$term=trim((string)($_GET['q']??''));
        if($category==='__categories__'){$results=$service->registrationCategories($destinationId);}
        else{$results=$service->searchRegistrationBusinesses($destinationId,$category,$term);}
        echo json_encode(['results'=>$results],JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);
    }catch(Throwable){http_response_code(400);echo '{"results":[]}';}exit;
}
$destinations=$service->registrationDestinations();$categories=$destinationId?$service->registrationCategories($destinationId):[];
try{
 if(!business_portal_available())throw new RuntimeException('El registro de cuentas empresariales todavía no está habilitado.');
 if($_SERVER['REQUEST_METHOD']==='POST'){
  csrf();if(!throttle('business_account_register_form',12,900))throw new RuntimeException('Demasiados intentos. Inténtalo más tarde.');
  if(($_POST['password']??'')!==($_POST['password_confirm']??''))throw new RuntimeException('Las contraseñas no coinciden.');
  $application=['application_type'=>(string)($_POST['application_type']??''),'business_id'=>(string)($_POST['business_id']??''),'business_name'=>(string)($_POST['business_name']??''),'destination_id'=>(string)($_POST['destination_id']??''),'category_code'=>(string)($_POST['category_code']??''),'relationship_code'=>(string)($_POST['relationship_code']??''),'phone'=>(string)($_POST['phone']??''),'message'=>(string)($_POST['message']??''),'consent'=>(string)($_POST['consent']??'')];
  $required=BusinessAccountPortalService::requiredEvidence($application['relationship_code']);
  foreach($required as $evidenceType){if(($_FILES[$evidenceType]['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('Adjunta los documentos obligatorios para validar tu identidad y relación con el negocio.');}
  $accountId=$service->register((string)($_POST['display_name']??''),(string)($_POST['email']??''),(string)($_POST['password']??''),$application,[
    'identity_document'=>$_FILES['identity_document']??[],
    'business_registration'=>$_FILES['business_registration']??[],
    'authority_document'=>$_FILES['authority_document']??[],
  ],private_storage_path('business-representation-evidence'));
  session_regenerate_id(true);$_SESSION['business_account_id']=$accountId;$_SESSION['business_last_seen']=time();$_SESSION['csrf']=bin2hex(random_bytes(32));
  header('Location: '.site_path('/negocios/portal/').'?solicitud=recibida',true,303);exit;
 }
}catch(Throwable $e){$error=$e instanceof PDOException?'Ya existe una cuenta con ese correo o no fue posible guardar la solicitud.':$e->getMessage();http_response_code(400);}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Registrar negocio | Explorando Lugares</title><link rel="stylesheet" href="<?=esc(site_path('/assets/style.css?v=business-portal-4'))?>"><link rel="stylesheet" href="<?=esc(site_path('/assets/admin.css?v=business-representation-1'))?>"><link rel="icon" href="<?=esc(site_path('/assets/favicon.svg'))?>" type="image/svg+xml"></head><body><main class="wrap admin-page account-portal"><a class="brand" href="<?=esc(site_path('/index.html'))?>"><img class="brand-logo" src="<?=esc(site_path('/assets/logo.svg'))?>" alt="" width="64" height="64"><span>Explorando<b>Lugares</b></span></a><p><a href="<?=esc(site_path('/negocios-locales/'))?>">← Negocios locales</a></p><section class="account-portal-card account-registration-card"><p class="eyebrow">Espacio para negocios</p><h1>Vincula tu negocio a una cuenta</h1><p>Primero buscamos si ya tenemos el negocio. Si no está en nuestros registros, puedes solicitar que lo revisemos. La cuenta no obtiene acceso para administrar el negocio hasta comprobar la identidad, la existencia del establecimiento y tu relación con él.</p><?php if($error):?><p class="notice" role="alert"><?=esc($error)?></p><?php endif ?><form method="post" enctype="multipart/form-data" class="registration-form" id="business-registration-form" data-search-url="<?=esc(site_path('/negocios/registro/'))?>"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><fieldset><legend>1. Busca el negocio</legend><div class="destination-form-grid"><label>Destino<select name="destination_id" id="registration-destination" required><option value="">Selecciona un destino</option><?php foreach($destinations as $item):?><option value="<?=esc($item['id'])?>" <?=$destinationId===(int)$item['id']?'selected':''?>><?=esc($item['display_name'])?></option><?php endforeach ?></select></label><label>Categoría<select name="category_code" id="registration-category" required <?=$categories?'':'disabled'?>><option value="">Selecciona una categoría</option><?php foreach($categories as $item):?><option value="<?=esc($item['code'])?>" <?=($_POST['category_code']??'')===$item['code']?'selected':''?>><?=esc($item['label'])?></option><?php endforeach ?></select></label><label class="wide">Nombre del negocio<input id="registration-search" type="search" autocomplete="off" placeholder="Escribe al menos dos letras" disabled><small>Buscamos negocios publicados y registros internos que aún no son visibles.</small></label></div><div id="registration-results" class="business-registration-results" aria-live="polite"><p>Selecciona destino y categoría para iniciar la búsqueda.</p></div><button type="button" class="pill light" id="registration-not-found" disabled>Mi negocio no aparece</button><input type="hidden" name="application_type" id="registration-application-type" value=""><input type="hidden" name="business_id" id="registration-business-id" value=""><label class="wide" id="registration-new-name-wrap" hidden>Nombre legal o comercial del negocio que falta<input name="business_name" id="registration-new-name" maxlength="180" autocomplete="organization"><small>La solicitud será privada; revisaremos que el negocio exista antes de crear su ficha.</small></label></fieldset><fieldset><legend>2. Identidad y relación con el negocio</legend><div class="destination-form-grid"><label>Tu nombre<input name="display_name" maxlength="180" autocomplete="name" required value="<?=esc($_POST['display_name']??'')?>"></label><label>Correo de contacto<input type="email" name="email" maxlength="254" autocomplete="email" required value="<?=esc($_POST['email']??'')?>"></label><label>Teléfono (opcional)<input type="tel" name="phone" maxlength="40" autocomplete="tel" value="<?=esc($_POST['phone']??'')?>"></label><label>Tu relación<select name="relationship_code" id="registration-relationship" required><option value="">Selecciona</option><option value="owner">Soy propietario/a</option><option value="legal_representative">Soy representante legal</option><option value="authorized_administrator">Soy administrador/a autorizado/a</option></select></label><label class="wide">Documento de identidad · PDF, JPG, PNG o WebP · máximo 8 MB<input type="file" name="identity_document" accept="application/pdf,image/jpeg,image/png,image/webp" required></label><label class="wide">Documento oficial del negocio · RUT, matrícula o certificado equivalente · máximo 8 MB<input type="file" name="business_registration" accept="application/pdf,image/jpeg,image/png,image/webp" required></label><label class="wide" id="registration-authority-wrap" hidden>Carta de autorización del representante legal · requerida para administradores autorizados<input type="file" name="authority_document" id="registration-authority-document" accept="application/pdf,image/jpeg,image/png,image/webp"></label><label class="wide">Información para revisar la solicitud<textarea name="message" rows="3" maxlength="1000" placeholder="Indica dónde aparece tu nombre o cómo podemos verificar la relación"><?=esc($_POST['message']??'')?></textarea></label></div><p class="small-note">Los documentos se guardan en un área privada y solo los consulta el equipo revisor. No se publican en el perfil del negocio.</p></fieldset><fieldset><legend>3. Crea tu acceso</legend><div class="destination-form-grid"><label>Contraseña<input type="password" name="password" minlength="12" maxlength="200" autocomplete="new-password" required><small>Al menos 12 caracteres, con letras y números.</small></label><label>Confirma la contraseña<input type="password" name="password_confirm" minlength="12" maxlength="200" autocomplete="new-password" required></label></div></fieldset><label class="admin-checkbox-field account-consent"><span>Autorizo el uso de mis datos y documentos para revisar y responder esta solicitud. Leí la <a href="<?=esc(site_path('/privacidad/'))?>" target="_blank" rel="noopener">política de tratamiento de datos</a>.</span><input type="checkbox" name="consent" value="1" required></label><button class="pill" type="submit" id="registration-submit" disabled>Crear cuenta y enviar a revisión</button></form><p>¿Ya tienes cuenta? <a href="<?=esc(site_path('/negocios/acceso/'))?>">Inicia sesión</a></p><div class="account-social-options"><strong>Acceso con otros proveedores</strong><p>Google y Microsoft se habilitarán cuando estén configurados. Por ahora, crea la cuenta con correo y contraseña.</p></div></section></main><script src="<?=esc(site_path('/assets/business-registration.js?v=4'))?>" defer></script></body></html>
